//! WOFF2 input: with the `woff2` feature the decoded font measures exactly like the TTF it
//! was made from (tests/data/*.woff2 is generated by tools/text/gen_text_cases.py with the
//! glyf, loca and hmtx transforms); without it, loading fails with `Unsupported`.

use std::path::Path;

use label_anything_text::{Font, TextError};

fn read(path: &str) -> Vec<u8> {
    std::fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join(path)).expect("test data")
}

#[cfg(feature = "woff2")]
#[test]
fn woff2_measures_like_the_ttf() {
    let woff2 =
        Font::from_bytes(read("tests/data/NotoSans-Regular.metrics.woff2")).expect("WOFF2 decodes");
    let ttf = Font::from_bytes(read("assets/NotoSans-Regular.metrics.ttf")).expect("TTF loads");
    let metrics = |f: &Font| (f.units_per_em(), f.ascender(), f.descender(), f.line_gap());
    assert_eq!(metrics(&woff2), metrics(&ttf));
    let cases: serde_json::Value =
        serde_json::from_slice(&read("../../../conformance/text/widths-400-12.json"))
            .expect("JSON");
    let texts: Vec<&str> = cases["widths"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| e["text"].as_str().unwrap())
        .collect();
    assert!(texts.len() > 60);
    for text in texts {
        assert_eq!(
            woff2.advance_units(text),
            ttf.advance_units(text),
            "{text:?}"
        );
    }
}

#[cfg(not(feature = "woff2"))]
#[test]
fn woff2_needs_the_feature() {
    let error = Font::from_bytes(read("tests/data/NotoSans-Regular.metrics.woff2")).unwrap_err();
    assert!(matches!(error, TextError::Unsupported(_)), "{error}");
}

#[test]
fn invalid_and_unsupported_data() {
    let message = |data: &[u8]| Font::from_bytes(data.to_vec()).unwrap_err();
    assert!(matches!(message(b""), TextError::InvalidFont(m) if m.contains("too short")));
    assert!(
        matches!(message(b"not a font at all"), TextError::InvalidFont(m) if m.contains("not a TrueType"))
    );
    assert!(
        matches!(message(b"wOFFxxxxxxxxxxxx"), TextError::Unsupported(m) if m.contains("WOFF 1.0"))
    );
    let ttf = read("assets/NotoSans-Regular.metrics.ttf");
    assert!(matches!(message(&ttf[..300]), TextError::InvalidFont(_)));
    // a valid font without its cmap table
    let mut broken = ttf.clone();
    let tables = usize::from(u16::from_be_bytes([broken[4], broken[5]]));
    for i in 0..tables {
        let at = 12 + 16 * i;
        if &broken[at..at + 4] == b"cmap" {
            broken[at..at + 4].copy_from_slice(b"xmap");
        }
    }
    assert!(matches!(message(&broken), TextError::InvalidFont(m) if m == "missing 'cmap' table"));
    assert_eq!(
        Font::from_bytes(ttf).map(|f| f.advance_units("\u{1F600}")),
        Ok(600),
        "unmapped code points use glyph 0"
    );
}
